files.content:
[hidden] { display: none !important; }

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #172b35;
  background: #e7f0e7;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background-color: #e7f0e7;
  background-image: linear-gradient(45deg, #d8e7da 25%, transparent 25%), linear-gradient(-45deg, #d8e7da 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #d8e7da 75%), linear-gradient(-45deg, transparent 75%, #d8e7da 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
}

.card {
  width: min(100%, 560px);
  padding: clamp(24px, 6vw, 48px);
  border: 3px solid #172b35;
  border-radius: 8px;
  background: #fffdf5;
  box-shadow: 10px 10px 0 #172b35;
}

.eyebrow, .result-label {
  margin: 0;
  color: #477568;
  font-size: .82rem;
  font-weight: 800;
  letter-spacing: .12em;
}

h1 {
  margin: 12px 0;
  font-size: clamp(2.3rem, 9vw, 3.8rem);
  line-height: .98;
  letter-spacing: -.055em;
}

.intro { margin: 0 0 28px; color: #43575c; }

.date-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
label { display: grid; gap: 8px; font-weight: 700; }
input {
  width: 100%; min-width: 0; min-height: 50px; padding: 10px;
  border: 2px solid #a9bdb0; border-radius: 5px; background: #fff;
  color: #172b35; font: inherit;
}
input:hover { border-color: #477568; }
input:focus-visible, button:focus-visible { outline: 3px solid #d97749; outline-offset: 3px; }

button {
  width: 100%; min-height: 54px; margin-top: 18px; padding: 12px 18px;
  border: 2px solid #172b35; border-radius: 5px; background: #d97749;
  color: #172b35; font: inherit; font-weight: 800; cursor: pointer;
  transition: transform .12s ease, box-shadow .12s ease, background .12s ease;
  box-shadow: 0 4px 0 #172b35;
}
button span { float: right; font-size: 1.25rem; }
button:hover { background: #e58b5f; transform: translateY(-2px); box-shadow: 0 6px 0 #172b35; }
button:active { transform: translateY(3px); box-shadow: 0 1px 0 #172b35; }

.results { display: grid; grid-template-columns: 1fr 150px; gap: 16px; margin-top: 28px; }
.result-main, .weeks-box { min-height: 132px; padding: 18px; border: 2px solid #172b35; border-radius: 5px; }
.result-main { display: flex; flex-direction: column; align-items: flex-start; justify-content: center; background: #dcebe0; }
.weeks-box { display: flex; flex-direction: column; align-items: flex-start; justify-content: center; background: #f5e6ad; }
.results strong { display: block; margin: 4px 0 2px; font-size: 3rem; line-height: 1; letter-spacing: -.06em; }
#order-result { color: #43575c; }
.note { margin: 16px 0 0; color: #63736e; font-size: .88rem; }

@media (max-width: 420px) {
  body { padding: 16px; }
  .card { box-shadow: 6px 6px 0 #172b35; }
  .date-fields { grid-template-columns: 1fr; gap: 12px; }
  .results { grid-template-columns: 1fr 112px; gap: 10px; }
  .result-main, .weeks-box { min-height: 120px; padding: 12px; }
  .results strong { font-size: 2.6rem; }
}

const form = document.getElementById('date-form');
const firstInput = document.getElementById('first-date');
const secondInput = document.getElementById('second-date');
const daysResult = document.getElementById('days-result');
const weeksResult = document.getElementById('weeks-result');
const orderResult = document.getElementById('order-result');

function calendarDay(value) {
  const [year, month, day] = value.split('-').map(Number);
  return Math.floor(Date.UTC(year, month - 1, day) / 86400000);
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;

  const first = calendarDay(firstInput.value);
  const second = calendarDay(secondInput.value);
  const difference = Math.abs(second - first);
  daysResult.textContent = String(difference);
  weeksResult.textContent = String(Math.floor(difference / 7));
  orderResult.textContent = second > first
    ? 'Second date is after the first'
    : second < first
      ? 'Second date is before the first'
      : 'Both dates are the same day';
});
